{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/24.0/apex.js")} 

// Validation Rule 
var query1 = "SELECT Id,(SELECT Id, Status__c FROM Proposals__r where Active__c=true AND (Status__c='Accepted by Customer' OR Status__c='Approval Required - Internal' OR Status__c='Acceptance Required - Customer')) FROM Opportunity where Id=\'{!Opportunity.Id}\' limit 1"; 

var oppRecords = sforce.connection.query(query1); 
var oppRecords1 = oppRecords.getArray('records'); 

if("{!Opportunity.StageName}" == 'Closed - Accepted' || "{!Opportunity.StageName}" == 'Closed - Not Accepted' ){ 

alert('Please note that you cannot create a proposal for a closed opportunity.'); 

}else if(oppRecords1[0].Proposals__r != null){ 

alert('Please note that you cannot create a new proposal for this opportunity since there is an existing active proposal.'); 

}else{ 

var rtype; 
if('{!Opportunity.Category__c}' == 'Qantas Business Savings'){ 
rtype = 'QBS - Draft'; 
}else if('{!Opportunity.Category__c}' == 'Corporate Airfares'){ 
rtype = 'CA - Draft'; 
}else if('{!Opportunity.Category__c}' == 'Adhoc'){ 
rtype = 'Adhoc Charter - Approval Required - Customer'; 
}else if('{!Opportunity.Category__c}' == 'Scheduled'){ 
rtype = 'Adhoc Charter - Approval Required - Customer'; 
}else if('{!Opportunity.Category__c}' == 'FIFO Scheduled'){ 
rtype = 'Adhoc Charter - Approval Required - Customer'; 
} 
var query = "SELECT Id, Name FROM RecordType where Name like '%"+rtype+"%' AND sObjectType='Proposal__c' limit 1";
var records = sforce.connection.query(query); 
var records1 = records.getArray('records'); 
var amnt = '{!Opportunity.Amount}';
amnt = amnt.substring(3,amnt.length);

window.top.location.href ='/a0H/e?CF00N9000000Dg8UI='+encodeURIComponent("{!Opportunity.Name}")+'&CF00N9000000Dg8UI_lkid={!Opportunity.Id}&CF00N9000000Dg8lB_lkid={!Opportunity.AccountId}&CF00N9000000Dg8lB='+encodeURIComponent("{!Opportunity.Account}")+'&00N9000000Dg8lx='+amnt+'&00N9000000Dg8lY={!Opportunity.Proposed_Market_Share__c}&00N9000000Dg8lg={!Opportunity.Proposed_International_Market_Share__c}&00N9000000Ezy91={!Text(Opportunity.Forecast_Charter_Spend__c)}&00N9000000EPJxr={!Text(Opportunity.Forecast_MCA_Revenue__c)}&00N9000000Dg8lX={!Opportunity.Deal_Type__c}&00N9000000Dg8lk={!Opportunity.Proposed_MCA_Routes_Market_Share__c}&RecordType='+records1[0].Id+'&00N9000000Dg8mJ={!Opportunity.Category__c}&retURL={!Opportunity.Id}&nooverride=1&CF00N9000000Dg8lU='+encodeURIComponent("{!Opportunity.Contact__c}")+'&CF00N9000000Dg8lU_lkid={!Opportunity.ContactId__c}';

}
